//! The icons of the interface: drawings from Codicons, the icons of Visual
//! Studio Code, kept as the path data of their SVG files and filled.
//!
//! Codicons are drawn for 16 pixels, with their lines on the pixel grid, so
//! they are sharp at the size they are used in. A set drawn for 24 pixels
//! and scaled down is not: its lines fall between the pixels.
//!
//! Only the drawings that are used are in here. To add one, take the `d`
//! attribute of its file in `src/icons` of the package.
//!
//! Codicons, https://github.com/microsoft/vscode-codicons, by Microsoft
//! Corporation, under the Creative Commons Attribution 4.0 International
//! license, https://creativecommons.org/licenses/by/4.0/. The path data is
//! unchanged; where a drawing is made of several paths they are joined.
//!
//! The one drawing of codn's own is its mark. Its path is written by
//! `scripts/mark.py` into `assets/mark.path`.
//!
//! One drawing is no path at all: the mark of a session at work, a glider
//! of the Game of Life on a small field, reckoned by the rules of the game
//! for every step it moves, see `glider`.
//!
//! No drawing is the mark of another. An agent is told by a drawing of
//! Codicons and by its name, never by the logo of its maker, which is
//! theirs to give and was not given.

use swash::zeno::{Fill, Mask, Transform};

use super::font::Raster;
use super::gl::MAX_ATLAS;

/// The side of the square most drawings are made on.
const GRID: f32 = 16.0;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Icon {
    /// The mark of codn. A filled shape as wide as its square of 95 and
    /// about 61 high, in the middle of it.
    Mark,
    /// Stands for a project.
    Folder,
    /// Stands for the branch of a project.
    GitBranch,
    /// Stands for starting something.
    Plus,
    /// Stands for a filter.
    Search,
    /// Stands for what changed.
    FileDiff,
    /// Stands for two panes side by side.
    Columns,
    /// Stands for closing.
    Close,
    /// Puts the window away.
    WindowMinimize,
    /// Makes the window fill the screen.
    WindowMaximize,
    /// Gives a window that fills the screen its own size back.
    WindowRestore,
    /// Closes the window.
    WindowClose,
    /// Leads on, or to the next of several.
    ChevronRight,
    /// Leads back, or to the one before.
    ChevronLeft,
    /// Stands before a folder that is open.
    ChevronDown,
    /// Leads from what stands above to what hangs on it: before the row
    /// of an agent below its session.
    Indent,
    /// Stands for the column at the right, while it is there and while
    /// it is folded away.
    SidebarRight,
    SidebarRightOff,
    /// Stands for the sidebar at the left, while it is whole and while
    /// it is folded to a strip.
    SidebarLeft,
    SidebarLeftOff,
    // What stands before a file in the column with the files, by the
    // kind its name tells.
    /// A file of no kind that is told apart.
    File,
    /// A file of source code.
    FileCode,
    /// A file of plain text.
    FileText,
    /// A file of data in braces.
    FileJson,
    /// A file of Markdown.
    FileMarkdown,
    /// Shows a file as it is meant, in the place of its text.
    OpenPreview,
    /// A picture, a sound or a film.
    FileMedia,
    /// A PDF.
    FilePdf,
    /// An archive.
    FileZip,
    /// A file that is not text.
    FileBinary,
    /// A link.
    FileLink,
    // What an agent can be given as its mark, by the name in `NAMED`.
    Sparkle,
    Code,
    Terminal,
    Agent,
    Robot,
    Wand,
    Star,
    Chip,
    Lightbulb,
    Beaker,
    // What a session is doing, see `chrome::state`.
    /// At rest.
    StateIdle,
    /// At work. A glider that moves over its field, see `STEPS`.
    StateWorking,
    /// It waits for the user.
    StateBlocked,
    /// It is done, and nobody has looked.
    StateDone,
    /// It failed.
    StateFailed,
    /// It stopped, and why is not known.
    StateAttention,
}

/// How many cells a side the field of the glider has. It is closed on
/// itself: what leaves at one side comes in at the other.
const FIELD: usize = 5;

/// After how many steps the mark of a session at work is where it began:
/// a glider moves one cell down and one to the right in four generations,
/// and is across its field after `FIELD` times that.
pub const STEPS: u8 = 4 * FIELD as u8;

/// How much of the color a cell of the field has in which nothing lives:
/// enough to show where the field is.
const EMPTY: u8 = 33;

/// The generation after `cells`, by the rules of the Game of Life: a cell
/// lives on with two or three neighbors that live, and one is born where
/// there are three. Bit `y * FIELD + x` is the cell in row `y` and column
/// `x`.
fn next(cells: u32) -> u32 {
    let lives = |x: usize, y: usize| cells >> (y % FIELD * FIELD + x % FIELD) & 1;
    let mut after = 0;
    for y in 0..FIELD {
        for x in 0..FIELD {
            // The eight around a cell, each one before, at and behind it:
            // counted from a whole field on, so that nothing goes below 0.
            let around = [(4, 4), (0, 4), (1, 4), (4, 0), (1, 0), (4, 1), (0, 1), (1, 1)];
            let neighbors: u32 = around.iter().map(|&(dx, dy)| lives(x + dx, y + dy)).sum();
            if neighbors == 3 || neighbors == 2 && lives(x, y) == 1 {
                after |= 1 << (y * FIELD + x);
            }
        }
    }
    after
}

/// The cells of the glider after `step` generations, see `next`. It is
/// reckoned and not kept as pictures: what moves there is the game.
fn glider(step: u8) -> u32 {
    // One cell in the first row, one in the second, three in the third.
    let begun = 1 << 1 | 1 << (FIELD + 2) | 0b111 << (2 * FIELD);
    (0..step % STEPS).fold(begun, |cells, _| next(cells))
}

/// The field of the glider as a square of `size` pixels. A cell and the
/// room between two are whole pixels, so every cell is sharp: of sixteen
/// pixels a cell has two and the room one, and one is left around. Where
/// a cell would have a single pixel the cells touch.
fn field(size: u32, step: u8) -> Raster {
    let side = size as usize;
    let mut room = ((size as f32 / GRID).round() as usize).max(1);
    let mut cell = side.saturating_sub((FIELD - 1) * room) / FIELD;
    if cell < 2 {
        (room, cell) = (0, (side / FIELD).max(1));
    }
    let around = side.saturating_sub(FIELD * cell + (FIELD - 1) * room) / 2;
    let (cells, mut data) = (glider(step), vec![0u8; side * side]);
    for at in 0..FIELD * FIELD {
        let (left, top) = (around + at % FIELD * (cell + room), around + at / FIELD * (cell + room));
        let ink = if cells >> at & 1 == 1 { 255 } else { EMPTY };
        for y in top..(top + cell).min(side) {
            for x in left..(left + cell).min(side) {
                data[y * side + x] = ink;
            }
        }
    }
    Raster { left: 0, top: 0, w: size, h: size, color: false, data }
}

